// Build setting: Compilation Mode
//   Whole Module (swiftc -wmo)
func area(w: Int, h: Int) -> Int { w * h }
print(area(w: 3, h: 4))

func twice<T: Numeric>(_ x: T) -> T { x + x }
// with -O, an Int-only copy is made
print(twice(21))

@inlinable
public func clamp(_ x: Int) -> Int {
    min(max(x, 0), 100)
}
print(clamp(250))

